import type { AssetType } from '../core/files.js';

/**
 * Table types. Conventions that keep SQLite, PostgreSQL and MariaDB alike:
 *   - ids are UUID strings generated by the app;
 *   - timestamps are ISO-8601 UTC strings (sortable as text);
 *   - booleans are integers 0/1;
 *   - grams and €/kg are doubles; money is integer cents.
 */
export type RecordStatus = 'indexed' | 'archived' | 'deleted';

/** One print: a (customer, project) pair on disk. */
export interface PrintRecordTable {
  id: string;
  /** "<customer>/<project>" or "<customer>/" for files directly under a customer. */
  record_key: string;
  customer_folder: string;
  project_folder: string | null;
  display_name: string;
  status: RecordStatus;
  discovered_at: string;
  last_seen_at: string;
  archived_at: string | null;
  deleted_at: string | null;
  deleted_by: string | null;
  /** Derived from the most recently modified counted G-code (else 3MF). */
  part_name: string | null;
  material: string | null;
  printer_model: string | null;
  /** Modification time of the most recent counted print file. */
  print_date: string | null;
  /** Sums over counted lines × times printed. */
  total_grams: number | null;
  total_print_seconds: number | null;
  updated_at: string;
  /** "Spoel voor de hele print": Spoolman id and the snapshot taken at assignment (JSON). */
  spool_id: number | null;
  spool_snapshot: string | null;
}

/** One file on disk belonging to a print. */
export interface PrintAssetTable {
  id: string;
  print_record_id: string;
  relative_path: string;
  /** SHA-256 of relative_path: unique index that fits every engine's key limits. */
  path_hash: string;
  file_name: string;
  /** Folders between the project (or customer) and the file, joined with "/". */
  sub_path: string;
  type: AssetType;
  size_bytes: number;
  last_write_utc: string;
  /** From the file name. */
  name_part: string | null;
  name_material: string | null;
  name_print_seconds: number | null;
  /** Timelapses: display only. */
  recorded_at: string | null;
  printer_prefix: string | null;
  /** From the file contents. */
  slicer: string | null;
  has_thumbnail: number;
  parse_error: string | null;
  indexed_at: string;
}

/**
 * A counted unit: a G-code file (plate_index 0) or one sliced 3MF plate.
 * User decisions (user_excluded, times_printed) survive re-indexing.
 */
export interface PrintLineTable {
  id: string;
  asset_id: string;
  plate_index: number;
  total_grams: number | null;
  print_seconds: number | null;
  printer_model: string | null;
  material: string | null;
  auto_excluded: number;
  /** "folder:<name>" or "gcode-present". */
  auto_exclusion_reason: string | null;
  /** Null follows auto_excluded; 0 or 1 is the user's choice. */
  user_excluded: number | null;
  duplicate_fingerprint: string | null;
  possible_duplicate: number;
}

export interface LineSlotTable {
  id: string;
  line_id: string;
  slot: number;
  grams: number;
  colour: string | null;
  material: string | null;
}

export type Role = 'User' | 'Editor' | 'Admin';

export interface UserTable {
  id: string;
  /** Lower-case sign-in name: an e-mail address or a plain name (OIDC: the e-mail address). */
  login: string;
  display_name: string;
  role: Role;
  /** argon2id hash; null for users who sign in through OIDC. */
  password_hash: string | null;
  oidc_subject: string | null;
  /** 1 when the role was set by OIDC_ADMIN_GROUP at the last sign-in. */
  role_from_group: number;
  /** 1 while the user still has a temporary password set by an Admin. */
  must_change_password: number;
  created_at: string;
  last_login_at: string | null;
}

/** Customer folders a User may see; Editors and Admins see every customer. */
export interface CustomerAccessTable {
  user_id: string;
  customer_folder: string;
  granted_at: string;
}

export interface SessionTable {
  id_hash: string;
  user_id: string;
  csrf_token: string;
  created_at: string;
  last_seen_at: string;
  expires_at: string;
}

export interface TagTable {
  id: string;
  /** As typed (trimmed, single spaces). */
  name: string;
  /** Lower-cased name, unique. */
  name_key: string;
  /** #rrggbb, or null for a chip without colour. */
  colour: string | null;
  created_at: string;
}

export interface PrintTagTable {
  print_record_id: string;
  tag_id: string;
}

/** Business settings as JSON values (pricing, printers, company). */
export interface AppSettingTable {
  key: string;
  value: string;
  updated_at: string;
  updated_by: string | null;
}

export interface CustomerTable {
  customer_folder: string;
  /** "Niet factureren": cost is tracked, but no sale price, payment or invoice. */
  no_billing: number;
  /**
   * An optional payment link the studio pastes, shown on the share page beside
   * the bank details (GAP-103). It carries its own amount, which Openstaand
   * cannot keep in step with, so it is never the primary action.
   */
  pay_link: string | null;
  /** When the link was last set, so an old link is visibly old. */
  pay_link_added_at: string | null;
  updated_at: string;
}

/**
 * Spool or manual price for one file or plate (slot 0) or one of its
 * filament slots, keyed by file path so it survives re-indexing.
 */
export interface LineOverrideTable {
  id: string;
  print_record_id: string;
  path_hash: string;
  plate_index: number;
  slot: number;
  spool_id: number | null;
  spool_snapshot: string | null;
  manual_price_per_kg: number | null;
  updated_at: string;
}

/** An order inside a print: order 1 always exists; later ones are repeat orders. */
export interface PrintOrderTable {
  id: string;
  print_record_id: string;
  number: number;
  created_at: string;
  created_by: string | null;
  sale_price_cents: number | null;
  sale_price_set_at: string | null;
  sale_price_set_by: string | null;
  /** "Kosten aanpassen" for this order; null means: calculated. */
  manual_price_per_kg: number | null;
  manual_grams: number | null;
  manual_print_seconds: number | null;
  written_off_cents: number | null;
  written_off_at: string | null;
  written_off_by: string | null;
  written_off_reason: string | null;
  material_cost_cents: number | null;
  electricity_cost_cents: number | null;
  total_cost_cents: number | null;
  /** Comma-separated MissingInput values from the last calculation. */
  cost_missing: string | null;
  updated_at: string;
  /** The final invoice this order is on; set means price and items are locked. */
  invoice_id: string | null;
}

/** A file or plate in an order, with how often it was printed for that order. */
export interface OrderItemTable {
  order_id: string;
  path_hash: string;
  plate_index: number;
  times_printed: number;
}

export interface PaymentTable {
  id: string;
  order_id: string;
  amount_cents: number;
  paid_at: string;
  recorded_by: string | null;
  /** Set by "Betaling ongedaan maken" (Admin); the row stays as history. */
  undone_at: string | null;
  undone_by: string | null;
}

export type InvoiceKind = 'invoice' | 'credit';

/** A final invoice or credit note (YYYY-NNN, one sequence per year). */
export interface InvoiceTable {
  id: string;
  number: string;
  year: number;
  sequence: number;
  kind: InvoiceKind;
  customer_folder: string;
  /** YYYY-MM-DD in Europe/Amsterdam. */
  issued_on: string;
  period_from: string | null;
  period_to: string | null;
  only_open: number;
  /** For a credit note: the invoice it corrects. */
  credits_invoice_id: string | null;
  total_cents: number;
  paid_cents: number;
  open_cents: number;
  reference: string;
  /** File name under DATA_DIR/invoices. */
  pdf_file: string;
  /** JSON of the document as issued (company, klant, lines, totals). */
  snapshot: string;
  created_at: string;
  created_by: string | null;
}

export interface InvoiceLineTable {
  id: string;
  invoice_id: string;
  position: number;
  order_id: string;
  print_record_id: string;
  description: string;
  project: string | null;
  line_date: string | null;
  grams: number | null;
  /** Negative on a credit note. */
  amount_cents: number;
  paid_cents: number;
  status: 'paid' | 'open' | 'partial' | null;
}

export interface ShareLinkTable {
  id: string;
  /** Hex SHA-256 of the token; the token itself is never stored. */
  token_hash: string;
  customer_folder: string;
  label: string;
  /** Null: Nooit (the link works until it is revoked). */
  expires_at: string | null;
  revoked_at: string | null;
  revoked_by: string | null;
  created_at: string;
  created_by: string | null;
}

export interface Database {
  print_records: PrintRecordTable;
  print_assets: PrintAssetTable;
  print_lines: PrintLineTable;
  line_slots: LineSlotTable;
  users: UserTable;
  customer_access: CustomerAccessTable;
  sessions: SessionTable;
  tags: TagTable;
  print_tags: PrintTagTable;
  app_settings: AppSettingTable;
  customers: CustomerTable;
  line_overrides: LineOverrideTable;
  print_orders: PrintOrderTable;
  order_items: OrderItemTable;
  payments: PaymentTable;
  invoices: InvoiceTable;
  invoice_lines: InvoiceLineTable;
  share_links: ShareLinkTable;
}
